function ModalCard({ title, children, onClose }) {
  return (
    <div style={{
      border: '1px solid #cbd5e1',
      borderRadius: '10px',
      padding: '20px',
      maxWidth: '400px',
      background: '#ffffff'
    }}>
      <h3 id="modal-title">{title}</h3>

      {/* TODO 1: Render children inside this content region. */}
      <div id="modal-content"></div>

